custom.preserve__2_search_finder_757.operation:
item.items = item.items
                .filter(e => {
                  let type = e.data?.card_type;
                  return type === 101 || type === 17;
                })
                .map(e => {
                  if (e.data?.card_type === 17) {
                    e.data.col = 1; // 强制单列
                  }
                  return e;
                });
